<?php require 'layout.php'; userStart('Wishlist',''); ?><div class="container"><div class="page-head"><span class="eyebrow">SAVED ITEMS</span><h1>My Wishlist</h1><p>Products you marked for later.</p></div><div id="wishlistArea" class="grid-4"></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const ids=JSON.parse(localStorage.getItem('surgical_wishlist')||'[]');const data={p1:['BP Monitor',1850,'bp-monitor.jpg'],p2:['Pulse Oximeter',999,'pulse-oximeter.jpg'],p3:['First Aid Kit',650,'first-aid-kit.jpg'],p4:['Digital Thermometer',299,'digital-thermometer.jpg'],p5:['Face Mask',120,'face-mask.jpg'],p6:['Surgical Gloves',250,'surgical-gloves.jpg'],p7:['Stethoscope',1250,'stethoscope.jpg'],p8:['Surgical Scissors',480,'surgical-scissors.jpg']};const area=document.getElementById('wishlistArea');if(!ids.length){area.innerHTML='<div class="card" style="grid-column:1/-1;text-align:center"><h2>No saved products yet</h2><p style="color:var(--muted)">Use the heart button on Products to save an item.</p><br><a class="btn primary" href="products.php">Browse Products</a></div>';return}ids.forEach(id=>{if(!data[id])return;const p=data[id];area.innerHTML+=`<div class="product-card"><img src="/SurgicalStore/images/${p[2]}" alt="${p[0]}"><div class="product-info"><h3>${p[0]}</h3><span class="price">₹${p[1]}</span><br><button class="btn primary small" onclick="addToCart('${id}','${p[0]}',${p[1]},'/SurgicalStore/images/${p[2]}')">Add to Cart</button></div></div>`})})</script><?php userEnd(); ?>
